import{g as t,o as e,c as s,ao as o}from"./chunks/framework.C_cxhC_b.js";const u=JSON.parse('{"title":"02 新建文章","description":"文章放哪里、frontmatter 每个字段干什么、文件名与链接的关系。","frontmatter":{"title":"02 新建文章","description":"文章放哪里、frontmatter 每个字段干什么、文件名与链接的关系。"},"headers":[],"relativePath":"notes/writing-guide/02-writing.md","filePath":"notes/writing-guide/02-writing.md","lastUpdated":1794066831000}'),n={name:"notes/writing-guide/02-writing.md"};function d(l,a,r,i,c,p){return e(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="新建文章" tabindex="-1">新建文章 <a class="header-anchor" href="#新建文章" aria-label="Permalink to &quot;新建文章&quot;">​</a></h1><p>文章放进 <code>docs/ai/</code> 这类普通目录即可，左侧目录按目录自动生成，不需要改配置。照下面这个模板起头：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">---</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">title: 文章标题</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">date: 2026-07-07</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">updated: 2026-07-08</span></span>
<span class="line"><span style="color:var(--shiki-foreground);font-weight:bold;"># 供「最后更新于」使用，必须带时区</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">lastUpdated: 2026-07-08T10:30:00+08:00</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">description: 一句话摘要，用于 SEO 和文章卡片</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">tags:</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">  - Markdown</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">---</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);font-weight:bold;"># 文章标题</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">&lt;NolebasePageProperties /&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);">正文第一段……</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-foreground);font-weight:bold;">## 小标题</span></span></code></pre></div><h2 id="字段分工" tabindex="-1">字段分工 <a class="header-anchor" href="#字段分工" aria-label="Permalink to &quot;字段分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>作用</th><th>不填会怎样</th></tr></thead><tbody><tr><td><code>title</code></td><td>侧栏标题、文章卡片标题</td><td>退回正文的一级标题</td></tr><tr><td><code>date</code></td><td>归档页排序依据</td><td>这篇<strong>不会进归档列表</strong>，也不显示日期</td></tr><tr><td><code>description</code></td><td>文章列表摘要、搜索结果</td><td>卡片上一片空白</td></tr><tr><td><code>tags</code></td><td>标签页聚合、卡片左上角的图标</td><td>没有标签胶囊，图标退回默认</td></tr><tr><td><code>updated</code></td><td>显示「更新于」</td><td>只显示创建日期</td></tr><tr><td><code>lastUpdated</code></td><td>「最后更新于」，精确到时间</td><td>用 git 提交时间兜底</td></tr><tr><td><code>icon</code></td><td>——</td><td>当前<strong>没有任何代码读取它</strong>，填了也不生效</td></tr></tbody></table><div class="rp-callout rp-callout--warning"><div class="rp-callout__title">只有 tags 决定图标</div><div class="rp-callout__content"><p>文章卡片的图标取自 <code>tags</code> 的第一个值，去 <code>tagIcons.ts</code> 里查表，查不到就用默认图标。<code>icon:</code> 是历史遗留字段，写了没有效果。</p></div></div><h2 id="文件名就是链接" tabindex="-1">文件名就是链接 <a class="header-anchor" href="#文件名就是链接" aria-label="Permalink to &quot;文件名就是链接&quot;">​</a></h2><p><code>docs/ai/qq-agent-mail.md</code> 会生成 <code>/ai/qq-agent-mail</code>。文件名用英文短横线，改文件名等于改链接，站内已有引用会一起断掉。</p><div class="rp-callout rp-callout--tip"><div class="rp-callout__title">路径规则</div><div class="rp-callout__content"><p><code>docs/public/</code> 映射到站点根路径，所以 <code>public/video/a.mp4</code> 写作 <code>/video/a.mp4</code>，<strong>不要</strong>带 <code>public</code>。详见 <a href="./05-media">图片与视频</a>。</p></div></div><h2 id="不要写-layout" tabindex="-1">不要写 layout <a class="header-anchor" href="#不要写-layout" aria-label="Permalink to &quot;不要写 layout&quot;">​</a></h2><p>普通文章不写 <code>layout</code>，写错会变成首页那种整页布局。可用的布局只有 <code>home</code>、<code>tags</code>、<code>posts</code>、<code>case</code>、<code>travel</code>，分别对应首页、标签页、归档页、旅途页和游记详情。</p><h2 id="正文结构" tabindex="-1">正文结构 <a class="header-anchor" href="#正文结构" aria-label="Permalink to &quot;正文结构&quot;">​</a></h2><ul><li>一级标题只出现一次，和 <code>title</code> 保持一致。</li><li><code>&lt;NolebasePageProperties /&gt;</code> 紧贴一级标题下方，负责渲染日期与标签胶囊。</li><li>二级标题用来分节，左侧目录会自动抓取，标题写得短一些更好读。</li></ul>`,13)])])}const g=t(n,[["render",d]]);export{u as __pageData,g as default};
